#include <stdio.h>
#include <stdlib.h>

#define MAXE 10000
#define MAXR 20000
#define INF 1000000000

typedef struct {
    int to, edge, next;
} Arc;

typedef struct {
    int dist, vertex;
} HeapItem;

static int E, R;
static int head[MAXE + 1];
static Arc arcs[2 * MAXR];
static int edgeU[MAXR], edgeV[MAXR], edgeW[MAXR];
static int bridge[MAXR];
static int timer;
static int tin[MAXE + 1], low[MAXE + 1];

static void find_bridges(int v, int parent_edge) {
    tin[v] = low[v] = ++timer;

    for (int a = head[v]; a != -1; a = arcs[a].next) {
        int edge = arcs[a].edge;
        int to = arcs[a].to;

        if (edge == parent_edge)
            continue;

        if (tin[to]) {
            if (tin[to] < low[v])
                low[v] = tin[to];
        } else {
            find_bridges(to, edge);

            if (low[to] < low[v])
                low[v] = low[to];

            if (low[to] > tin[v])
                bridge[edge] = 1;
        }
    }
}

static void heap_push(HeapItem *heap, int *size, int dist, int vertex) {
    int i = (*size)++;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].dist <= dist)
            break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i].dist = dist;
    heap[i].vertex = vertex;
}

static HeapItem heap_pop(HeapItem *heap, int *size) {
    HeapItem result = heap[0];
    HeapItem last = heap[--(*size)];
    int i = 0;

    while (2 * i + 1 < *size) {
        int child = 2 * i + 1;
        if (child + 1 < *size && heap[child + 1].dist < heap[child].dist)
            child++;

        if (heap[child].dist >= last.dist)
            break;

        heap[i] = heap[child];
        i = child;
    }

    if (*size > 0)
        heap[i] = last;

    return result;
}

