                continue;

            long long candidate = 2LL * dist[v] + cycleLength[id];
            if (answer == -1 || candidate < answer)
                answer = candidate;
        }

        printf("%lld\n", answer);
    }

    free(heap);
    free(cycleLength);
    return 0;
